def solve_quasigroup_sat():
    n = 6

    # x[i][j] = v is represented by variable (i*n + j)*n + v + 1
    def var(i, j, v):
        return (i * n + j) * n + v + 1

    solver = Glucose3()

    # Each cell has exactly one value
    for i in range(n):
        for j in range(n):
            # At least one value
            solver.add_clause([var(i, j, v) for v in range(n)])
            # At most one value
            for v1 in range(n):
                for v2 in range(v1+1, n):
                    solver.add_clause([-var(i, j, v1), -var(i, j, v2)])

    # Each row has each value exactly once
    for i in range(n):
        for v in range(n):
            # At least one column has value v
            solver.add_clause([var(i, j, v) for j in range(n)])
            # At most one column has value v
            for j1 in range(n):
                for j2 in range(j1+1, n):
                    solver.add_clause([-var(i, j1, v), -var(i, j2, v)])

    # Each column has each value exactly once
    for j in range(n):
        for v in range(n):
            # At least one row has value v
            solver.add_clause([var(i, j, v) for i in range(n)])
            # At most one row has value v
            for i1 in range(n):
                for i2 in range(i1+1, n):
                    solver.add_clause([-var(i1, j, v), -var(i2, j, v)])

    # Idempotent diagonal
    for i in range(n):
        solver.add_clause([var(i, i, i)])

    # QG3: x[x[i][j]][x[j][i]] = i
    # For each i, j, and for each possible a = x[i][j], b = x[j][i], we need x[a][b] = i
    # This means: if x[i][j] = a and x[j][i] = b, then x[a][b] = i
    # In CNF: -x[i][j]=a OR -x[j][i]=b OR x[a][b]=i
    for i in range(n):
        for j in range(n):
            for a in range(n):
                for b in range(n):
                    solver.add_clause([-var(i, j, a), -var(j, i, b), var(a, b, i)])

    print(f"Variables: {solver.nof_vars()}, Clauses: {solver.nof_clauses()}")
    print("Solving...")

    if solver.solve():
        model = solver.get_model()
        grid = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for v in range(n):
