        grid[i][i] = i
        row_used[i].add(i)
        col_used[i].add(i)

    # Order cells to fill (skip diagonal)
    cells = [(i, j) for i in range(n) for j in range(n) if i != j]

    def is_valid(i, j, v):
        if v in row_used[i] or v in col_used[j]:
            return False
        return True

    def check_qg3_partial():
        # Check QG3 for all pairs where all three cells are filled
