import sys

def solve_with_mrv():
    n = 6

    grid = [[-1]*n for _ in range(n)]
    row_used = [set() for _ in range(n)]
    col_used = [set() for _ in range(n)]

    # Set diagonal
    for i in range(n):
        grid[i][i] = i
        row_used[i].add(i)
        col_used[i].add(i)

    # Forward checking: maintain possible values for each cell
    possible = [[set(range(n)) for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            possible[i][j].discard(i)  # diagonal already set
            if i == j:
                possible[i][j] = {i}

    def update_possible(i, j, v):
        """Remove v from row i and column j possibilities"""
        changes = []
        for k in range(n):
            if k != j and v in possible[i][k]:
                possible[i][k].discard(v)
                changes.append((i, k, v))
            if k != i and v in possible[k][j]:
                possible[k][j].discard(v)
                changes.append((k, j, v))
        return changes

    def restore_possible(changes):
        for i, j, v in changes:
            possible[i][j].add(v)

    def check_qg3_implications(i, j, v):
        """Check if setting x[i][j] = v creates QG3 conflicts"""
        # If x[i][j] = v, then for QG3: x[v][x[j][i]] = i
        # If x[j][i] is already set to w, then x[v][w] must be i
        if grid[j][i] >= 0:
            w = grid[j][i]
            if grid[v][w] >= 0 and grid[v][w] != i:
                return False
            if grid[v][w] == -1 and i not in possible[v][w]:
                return False

        # Also check: if x[j][i] = v (symmetric case), then x[v][x[i][j]] = j
        # But x[i][j] = v, so x[v][v] = j, but x[v][v] = v (diagonal), so j = v
        # This is only a problem if j != v
        # Wait, this is about x[j][i], not x[i][j]

        # Check reverse: x[x[j][i]][x[i][j]] = j
        # If x[j][i] is set to w and x[i][j] = v, then x[w][v] = j
        if grid[j][i] >= 0:
            w = grid[j][i]
            if grid[w][v] >= 0 and grid[w][v] != j:
                return False
            if grid[w][v] == -1 and j not in possible[w][v]:
                return False

        return True

    def get_unfilled_cells():
        cells = []
        for i in range(n):
            for j in range(n):
                if grid[i][j] == -1:
                    cells.append((i, j))
        return cells

    def solve():
        cells = get_unfilled_cells()
        if not cells:
            return True

        # MRV: pick cell with fewest possibilities
        best_cell = None
        best_count = n + 1
        for i, j in cells:
            count = len(possible[i][j])
            if count < best_count:
                best_count = count
                best_cell = (i, j)
            if count == 0:
                return False  # Dead end

        i, j = best_cell

        for v in list(possible[i][j]):
            if v in row_used[i] or v in col_used[j]:
                continue

            if not check_qg3_implications(i, j, v):
                continue

            # Try this value
            grid[i][j] = v
            row_used[i].add(v)
            col_used[j].add(v)
            changes = update_possible(i, j, v)

            if solve():
                return True

            # Backtrack
            grid[i][j] = -1
            row_used[i].remove(v)
            col_used[j].remove(v)
            restore_possible(changes)

        return False

    if solve():
        for row in grid:
            print(row)
        flat = [grid[i][j] for i in range(n) for j in range(n)]
        return flat
    else:
        return None

